def blocks(g,sepv):
    rs=[r for r,row in enumerate(g) if len(set(row))==1 and row[0]==sepv]
    cs=[c for c in range(len(g[0])) if all(g[r][c]==sepv for r in range(len(g)))]
    return rs,cs
def solve(g,sepv,noise):
    rs,cs=blocks(g,sepv); H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    for (a,b) in splits(rs,H):
        for (c,d) in splits(cs,W):
            blk=[row[c:d] for row in g[a:b]]
            flat=[x for r in blk for x in r]
            bg=max(Counter(flat).items(),key=lambda kv:kv[1])[0]
            n=sum(r.count(noise) for r in blk)
            area=(b-a)*(d-c)
            if n*2>=area:
                for i in range(a,b):
                    for j in range(c,d): out[i][j]=noise
    return out
