import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def solve(I):
    h,w=len(I),len(I[0])
    def lines(color):
        L=[]
        for i in range(h):
            if all(I[i][j]==color for j in range(w)): L.append(('r',i))
        for j in range(w):
            if all(I[i][j]==color for i in range(h)): L.append(('c',j))
        return L
    seps=[c for c in set(v for r in I for v in r) if len(lines(c))>0]
    sep=min(seps,key=lambda c:sum(r.count(c) for r in I))
    rs=[i for i in range(h) if all(I[i][j]==sep for j in range(w))]
    cs=[j for j in range(w) if all(I[i][j]==sep for i in range(h))]
    vals=Counter(v for r in I for v in r)
    other={c:v for c,v in vals.items() if c!=sep}
    fill=min(other,key=other.get)
    rb=[]; prev=0
    for s in rs+[h]:
        if s>prev: rb.append((prev,s)); prev=s+1
    cb=[]; prev=0
    for s in cs+[w]:
        if s>prev: cb.append((prev,s)); prev=s+1
    counts={}
    for a,b in rb:
        for c,d in cb:
            n=sum(1 for x in range(a,b) for y in range(c,d) if I[x][y]==fill)
            counts[(a,c)]=n
    mx=max(counts.values())
    out=[r[:] for r in I]
    for a,b in rb:
        for c,d in cb:
            if counts[(a,c)]==mx and counts[(a,c)]>0:
                for x in range(a,b):
                    for y in range(c,d):
                        if I[x][y]!=sep: out[x][y]=fill
    return out

