def solve(I):
    h,w=len(I),len(I[0])
    def lines(color):
        L=[]
        for i in range(h):
            if all(I[i][j]==color for j in range(w)): L.append(('r',i))
        for j in range(w):
            if all(I[i][j]==color for i in range(h)): L.append(('c',j))
        return L
    seps=[c for c in set(v for r in I for v in r) if len(lines(c))>0]
    sep=min(seps,key=lambda c:sum(r.count(c) for r in I))
    vals=Counter(v for r in I for v in r)
    fill=min([c for c in vals if c not in (sep,) and c!=sep],key=lambda c:vals[c])
    # background = most common excluding sep and fill
    rest={c:v for c,v in vals.items() if c not in (sep,fill)}
    bg=max(rest,key=rest.get) if rest else 6
    rs=[i for i in range(h) if all(I[i][j]==sep for j in range(w))]
    cs=[j for j in range(w) if all(I[i][j]==sep for i in range(h))]
    rb=[]; prev=0
    for s in rs+[h]:
        if s>prev: rb.append((prev,s)); prev=s+1
    cb=[]; prev=0
    for s in cs+[w]:
        if s>prev: cb.append((prev,s)); prev=s+1
    out=[r[:] for r in I]
    for a,b in rb:
        for c,d in cb:
            n=sum(1 for x in range(a,b) for y in range(c,d) if I[x][y]==fill)
            if n==max(counts.values()) if False else True: pass
    mx=0
    for a,b in rb:
        for c,d in cb:
            n=sum(1 for x in range(a,b) for y in range(c,d) if I[x][y]==fill)
            mx=max(mx,n)
    for a,b in rb:
        for c,d in cb:
            n=sum(1 for x in range(a,b) for y in range(c,d) if I[x][y]==fill)
            if n>0 and n==mx:
                for x in range(a,b):
                    for y in range(c,d):
                        if I[x][y]!=sep: out[x][y]=fill
            elif n>0 and n<mx:
                for x in range(a,b):
                    for y in range(c,d):
                        if I[x][y]==fill: out[x][y]=bg
    return out

